from functools import lru_cache

N_x = lambda: int(input())

N = N_x()

@lru_cache
def n_split(x: int) -> int:
    if x < 2:
        return 0
    else:
        if x % 2 == 0:
            return n_split(x // 2) + n_split(x // 2) + x
        else:
            return n_split(x // 2) + n_split(x // 2 + 1) + x

ans = n_split(N)
print(ans)
